returned_quantity, null AS returned_sales, null AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, null AS Days_in_Shipment, NULL AS ACQUISITION_DATE, null AS SKU_CODE, null AS PRODUCT_NAME_FINAL, null AS PRODUCT_CATEGORY, null AS PRODUCT_SUB_CATEGORY, null AS commonsku, null AS WAREHOUSE, null AS pincode, null as source_pincode, null as discount_codes from `Maplemonk.Varak_s3_order_sales_fact_items` a where a.order_id not in (select distinct order_id from `Maplemonk.Varak_s3_item_sales_fact_items`); CREATE OR REPLACE TABLE varak-wh.Maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM varak-wh.Maplemonk.varak_s3_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM varak-wh.Maplemonk.varak_s3_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE varak-wh.Maplemonk.varak_s3_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.* EXCEPT(acquisition_date) FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM varak-wh.Maplemonk.varak_s3_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM varak-wh.Maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM varak-wh.Maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN varak-wh.Maplemonk.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace); ALTER TABLE varak-wh.Maplemonk.varak_s3_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE varak-wh.Maplemonk.varak_s3_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE varak-wh.Maplemonk.varak_s3_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM varak-wh.Maplemonk.varak_s3_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE varak-wh.Maplemonk.varak_s3_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE varak-wh.Maplemonk.varak_s3_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM varak-wh.Maplemonk.varak_s3_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE varak-wh.Maplemonk.varak_s3_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, channel, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM varak-wh.Maplemonk.varak_s3_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE varak-wh.Maplemonk.varak_s3_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE varak-wh.Maplemonk.varak_s3_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM varak-wh.Maplemonk.varak_s3_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE varak-wh.Maplemonk.varak_s3_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final;",
